import MiniSearch from "minisearch";
import docsIndex from "./docsIndex.json";

/** One chunk of a markdown file under docs/, generated by `yarn chat:index`. */
export type DocChunk = {
  id: number;
  path: string;
  heading: string;
  text: string;
};

// Question words that match almost every chunk and push the relevant ones down.
const STOP_WORDS = new Set(
  (
    "a an and are as at be but by can do does did for from has have how i if in is it its me my of on or our " +
    "please should so tell than that the their them then there these they this to us was we what when where " +
    "which who why will with would you your about explain describe show list give work works working"
  ).split(" "),
);

const queryTerm = (term: string) => {
  const lower = term.toLowerCase();
  return STOP_WORDS.has(lower) ? null : lower;
};

let search: MiniSearch<DocChunk> | undefined;

function getSearch(): MiniSearch<DocChunk> {
  if (!search) {
    search = new MiniSearch<DocChunk>({
      fields: ["heading", "text", "path"],
      storeFields: ["path", "heading", "text"],
      searchOptions: {
        boost: { heading: 3, path: 2 },
        prefix: true,
        fuzzy: 0.2,
        processTerm: queryTerm,
      },
    });
    search.addAll(docsIndex as DocChunk[]);
  }
  return search;
}

/** At most this many chunks come from one file, so code chunks aren't crowded out by one long doc. */
export const MAX_CHUNKS_PER_FILE = 3;

/** Returns the doc and code chunks that best match the query, best first. */
export function searchDocs(query: string, limit = 8): DocChunk[] {
  const perFile = new Map<string, number>();
  const chunks: DocChunk[] = [];
  for (const result of getSearch().search(query)) {
    const count = perFile.get(result.path) ?? 0;
    if (count >= MAX_CHUNKS_PER_FILE) continue;
    perFile.set(result.path, count + 1);
    chunks.push({
      id: result.id,
      path: result.path,
      heading: result.heading,
      text: result.text,
    });
    if (chunks.length === limit) break;
  }
  return chunks;
}
